<script setup lang="ts">
import ConsoleDrawer from '../console/ConsoleDrawer.vue'
import ConsoleDiscardChangesDialog from '../console/ConsoleDiscardChangesDialog.vue'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import {dateTime} from '../../utils/update-center'
const props=defineProps<{endpoint:string;canWrite:boolean}>(),emit=defineEmits<{close:[];saved:[]}>(),auth=useApi('tenant')
type Assets={points:{amount:number;version:number};balance:{amount:number;version:number}}
type Entry={id:string;kind:string;delta:number;beforeAmount:number;afterAmount:number;reference:string;createdAt:string}
const data=ref<Assets|null>(null),enabled=ref(false),asset=ref('points'),records=ref<{items:Entry[];total:number;page:number;pageSize:number}>({items:[],total:0,page:1,pageSize:20}),action=ref(''),reading=ref(''),error=ref(''),recordError=ref(''),form=reactive({kind:'gift',amount:'',reason:''}),attempt=ref<any>(null),baseline=ref(JSON.stringify(form)),discard=useDiscardChanges(()=>!!action.value),lifetime=new AbortController();let controller:AbortController|undefined,sequence=0,disposed=false
const dirty=computed(()=>baseline.value!==JSON.stringify(form)),money=(n:number)=>(n<0?'-':'')+Math.trunc(Math.abs(n)/100)+'.'+String(Math.abs(n%100)).padStart(2,'0'),label:Record<string,string>={'recharge.paid':'充值到账','recharge.gift':'充值赠送',spend:'消费',return:'原路退回',gift:'赠送积分',adjust:'调整扣除','refund.revoke':'退款回收'}
const pendingKey='wallet:'+auth.session.value?.id+':'+props.endpoint
async function load(source='load'){if(action.value||disposed)return;action.value=source;error.value='';try{const result=await auth.api<{assets:Assets;enabled:boolean}>(props.endpoint,'GET',undefined,{signal:lifetime.signal});if(!disposed){data.value=result.assets;enabled.value=result.enabled===true}}catch(e:any){if(!disposed)error.value=e.message||'读取失败'}finally{if(!disposed)action.value=''}}
async function loadRecords(source='tab',page=1){if(disposed)return;controller?.abort();controller=new AbortController();const current=++sequence;reading.value=source;try{const result=await auth.api<typeof records.value>(props.endpoint+'/'+asset.value+'/records?page='+page,'GET',undefined,{signal:AbortSignal.any([controller.signal,lifetime.signal])});if(!disposed&&current===sequence){records.value=result;recordError.value=''}}catch(e:any){if(!disposed&&current===sequence)recordError.value=e.message||'流水读取失败'}finally{if(!disposed&&current===sequence)reading.value=''}}
function selectAsset(value:string){asset.value=value;records.value={items:[],total:0,page:1,pageSize:20};void loadRecords()}
function close(){if(action.value)return;if(dirty.value||attempt.value){discard.request(()=>emit('close'));return}emit('close')}
async function save(){if(action.value||!data.value||!props.canWrite||!enabled.value)return;error.value='';if(!attempt.value){const amount=Number(form.amount);if(!Number.isInteger(amount)||amount<1||amount>1000000||!form.reason.trim()){error.value='请填写整数积分和操作原因';return}attempt.value={requestKey:crypto.randomUUID(),version:data.value.points.version,kind:form.kind,amount,reason:form.reason.trim()}}try{sessionStorage.setItem(pendingKey,JSON.stringify(attempt.value))}catch{attempt.value=null;error.value='无法保存恢复信息，本次未提交';return}action.value='save';try{const result=await auth.api<{assets:Assets;enabled:boolean}>(props.endpoint,'POST',attempt.value,{signal:lifetime.signal});if(!disposed){data.value=result.assets;enabled.value=result.enabled===true;attempt.value=null;sessionStorage.removeItem(pendingKey);Object.assign(form,{kind:'gift',amount:'',reason:''});baseline.value=JSON.stringify(form);emit('saved');await loadRecords('mutation')}}catch(e:any){if(!disposed){error.value=e.message||'结果待确认，请查询原操作';if(e.status&&e.status<500){attempt.value=null;sessionStorage.removeItem(pendingKey)}}}finally{if(!disposed)action.value=''}}
onMounted(()=>{try{const raw=sessionStorage.getItem(pendingKey);if(raw){attempt.value=JSON.parse(raw);Object.assign(form,{kind:attempt.value.kind,amount:String(attempt.value.amount),reason:attempt.value.reason})}}catch{}void load();void loadRecords('initial')})
onBeforeRouteLeave(to=>{if(action.value)return false;if(dirty.value||attempt.value){discard.request(()=>{emit('close');void navigateTo(to.fullPath)});return false}})
onBeforeUnmount(()=>{disposed=true;sequence++;controller?.abort();lifetime.abort()})
</script>
<template><ConsoleDrawer open title="账户资产" wide :dismissible="!action" @update:open="!$event&&close()"><template #body><div class="space-y-6"><UAlert v-if="error" color="error" :title="error"><template v-if="!data" #actions><UButton :loading="action==='retry'" @click="load('retry')">重试</UButton></template></UAlert><p v-if="action==='load'" role="status">正在读取资产…</p><UAlert v-if="data&&!enabled" color="neutral" title="本站尚未启用公共钱包" description="请先在充值管理保存配置，再调整积分。"/><dl v-if="data" class="drawer-facts"><dt>积分</dt><dd>{{data.points.amount}}</dd><dt>人民币余额</dt><dd>¥ {{money(data.balance.amount)}}</dd></dl>
 <section class="space-y-4"><div class="flex gap-3"><UButton v-for="tab in [{value:'points',label:'积分明细'},{value:'balance',label:'余额明细'}]" :key="tab.value" :variant="asset===tab.value?'solid':'outline'" @click="selectAsset(tab.value)">{{tab.label}}</UButton></div><p v-if="reading&&reading!=='mutation'" role="status" class="text-sm text-muted">正在读取流水…</p><UAlert v-if="recordError" color="error" :title="recordError"><template #actions><UButton :loading="reading==='retry'" @click="loadRecords('retry',records.page)">重试</UButton></template></UAlert><p v-if="!reading&&!recordError&&!records.items.length" class="text-sm text-muted">暂无流水</p><article v-for="entry in records.items" :key="entry.id" class="border-b border-default py-3"><div class="flex justify-between gap-4"><span>{{label[entry.kind]||entry.kind}}</span><strong class="tabular-nums">{{entry.delta>0?'+':''}}{{asset==='points'?entry.delta:money(entry.delta)}}</strong></div><p class="mt-1 text-xs text-muted">{{dateTime(entry.createdAt)}} · 变动后 {{asset==='points'?entry.afterAmount:money(entry.afterAmount)}}</p><p class="mt-1 break-all text-xs text-muted">关联：{{entry.reference}}</p></article><div v-if="records.total>20" class="flex justify-end gap-3"><UButton variant="outline" :disabled="records.page===1||!!reading" @click="loadRecords('page',records.page-1)">上一页</UButton><UButton variant="outline" :disabled="records.page*20>=records.total||!!reading" @click="loadRecords('page',records.page+1)">下一页</UButton></div></section>
 <form v-if="canWrite&&data&&enabled" id="wallet-adjust" class="space-y-5 border-t border-default pt-5" @submit.prevent="save"><h3 class="drawer-section-title">调整积分</h3><ConsoleSettingsField label="调整方式"><URadioGroup v-model="form.kind" :items="[{label:'增加赠送',value:'gift'},{label:'扣除调整',value:'adjust'}]" orientation="horizontal" :disabled="!!action||!!attempt"/></ConsoleSettingsField><ConsoleSettingsField label="积分数量"><ConsoleInput v-model="form.amount" type="number" min="1" max="1000000" step="1" required :disabled="!!action||!!attempt"/></ConsoleSettingsField><ConsoleSettingsField label="操作原因"><UTextarea v-model="form.reason" required :maxlength="200" class="w-full" :disabled="!!action||!!attempt"/></ConsoleSettingsField><p v-if="attempt&&!action" role="status">原操作结果待确认，请使用原请求查询。</p></form>
</div></template><template #footer><ConsoleFormActions><UButton color="neutral" variant="outline" :disabled="!!action" @click="close">关闭</UButton><UButton v-if="canWrite&&data&&enabled" form="wallet-adjust" type="submit" :loading="action==='save'" :disabled="!!action||(!dirty&&!attempt)">{{attempt?'查询原操作':'确认调整'}}</UButton></ConsoleFormActions></template></ConsoleDrawer><ConsoleDiscardChangesDialog :controller="discard"/></template>
